import { test, expect } from '@playwright/test';

test.describe('Page Title Update on Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should update page title when navigating between sections', async ({ page }) => {
    // Verify initial page title
    const pageTitle = page.getByRole('heading', { name: /Dashboard/i });
    await expect(pageTitle).toBeVisible();

    // Verify initial URL
    const url = page.url();
    expect(url).toContain('/dashboard');

    // Navigate to the overview section
    const overviewNav = page.getByRole('navigation', { name: /overview/i });
    await overviewNav.click();

    // Verify page title updates
    const overviewTitle = page.getByRole('heading', { name: /Overview/i });
    await expect(overviewTitle).toBeVisible();

    // Verify URL changes
    const overviewUrl = page.url();
    expect(overviewUrl).toContain('/dashboard/overview');

    // Navigate back to the dashboard
    const backNav = page.getByRole('navigation', { name: /back/i });
    await backNav.click();

    // Verify page title reverts to dashboard
    const dashboardTitle = page.getByRole('heading', { name: /Dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    // Verify URL reverts to initial state
    const dashboardUrl = page.url();
    expect(dashboardUrl).toContain('/dashboard');
  });

  test('should handle navigation to non-existent sections gracefully', async ({ page }) => {
    // Navigate to a non-existent section
    const nonExistentNav = page.getByRole('navigation', { name: /reports/i });
    await nonExistentNav.click();

    // Verify page title does not update
    const pageTitle = page.getByRole('heading', { name: /Dashboard/i });
    await expect(pageTitle).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/Section not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify URL remains unchanged
    const currentUrl = page.url();
    expect(currentUrl).toContain('/dashboard');
  });
});
